<?php
namespace Modules\Ran\Http\Controllers;
use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{Item,Metal,Purity,Design,Gemstone};use Modules\Ran\Http\Requests\ItemRequest;use Modules\Ran\Services\AuditService;
class ItemController extends RanController {public function index(){return view('ran::items.index',array_merge($this->pageOptions(),['items'=>Item::with(['metal','purity'])->latest('id')->paginate(25)]));} private function options(){return array_merge($this->pageOptions(),['metals'=>Metal::where('is_active',1)->pluck('name','id'),'purities'=>Purity::where('is_active',1)->pluck('name','id'),'designs'=>Design::where('is_active',1)->pluck('name','id'),'gemstones'=>Gemstone::where('is_active',1)->pluck('name','id')]);} public function create(){return view('ran::items.form',array_merge($this->options(),['item'=>null]));} public function store(ItemRequest $request,AuditService $audit){$item=DB::transaction(function()use($request,$audit){$data=$request->safe()->except('components');$item=Item::create($data);foreach($request->validated('components',[]) as $line){if(!empty($line['component_type']))$item->components()->create(array_merge(['business_id'=>$item->business_id],$line));}$audit->record('created',$item);return $item;});return $this->success('Jewellery item added successfully.','ran.items.index');} public function edit(Item $item){return view('ran::items.form',array_merge($this->options(),['item'=>$item->load('components')]));} public function update(ItemRequest $request,Item $item,AuditService $audit){DB::transaction(function()use($request,$item,$audit){$old=$item->getAttributes();$item->update($request->safe()->except('components'));$item->components()->delete();foreach($request->validated('components',[]) as $line){if(!empty($line['component_type']))$item->components()->create(array_merge(['business_id'=>$item->business_id],$line));}$audit->record('updated',$item,null,$old,$item->getAttributes());});return $this->success('Jewellery item updated successfully.','ran.items.index');} public function destroy(Item $item,AuditService $audit){if($item->stockLots()->where('stock_status','available')->exists())return back()->withErrors('This item has available stock and cannot be deleted.');$audit->record('deleted',$item);$item->delete();return back()->with('status','Jewellery item removed.');}}
